package io.github.diodeme.ji.artifact;

import java.time.Instant;
import java.util.Collection;
import java.util.List;

/** Content-addressed artifact port. Workspace source files are not artifacts. */
public interface ArtifactStore extends AutoCloseable {
    ArtifactReceipt putDirect(DirectUpload upload, Instant now);
    UploadHandle beginUpload(ResumableUpload upload, Instant now);
    void putChunk(String uploadId, UploadChunk chunk, Instant now);
    ArtifactReceipt complete(String uploadId, Instant now);
    void abort(String uploadId);
    ArtifactRead read(ArtifactId artifactId, ArtifactScope scope, ByteRange range);
    List<ArtifactReference> references(ArtifactId artifactId);
    void removeReference(String referenceId, Instant now);
    void pin(ArtifactId artifactId, ArtifactScope scope);
    void unpin(ArtifactId artifactId, ArtifactScope scope, Instant now);
    ArtifactUsage usage();
    int cleanupIncomplete(Instant now);
    int collectOrphans(Instant now);
    ArtifactValidationReport validate(Collection<ArtifactId> referencedIds);
    @Override default void close() {}
}
